const size_t dynlib_numfunctions = sizeof(dynlib_functions) / sizeof(*dynlib_functions);

/* dlsym() backing for the module.
 *
 * This is not only for completeness. The engine dlopen()s libOpenSLES.so and
 * resolves slCreateEngine and the SL_IID_* interface ids through dlsym at
 * runtime -- none of them appears in the library's import table, so without
 * this lookup the audio system would initialise, find nothing, and play
 * silence with no error reported anywhere. */
uintptr_t dynlib_find_export(const char *name) {
  DynLibFunction *f = so_find_import(dynlib_functions, (int)dynlib_numfunctions, name);
  return f ? f->func : 0;
}
